const ScrollToTop = () => {
  const { pathname } = useLocation();
  React.useEffect(() => {
    // Only scroll to top if not a hash link
    if (!window.location.hash) {
      window.scrollTo(0, 0);
    }
  }, [pathname]);
  return null;
};

